import {
  deriveTimePeriodSelection,
  getDefaultTimePeriodEnd,
  isCanonicalMonthStartDate,
  isTimePeriodSelectionAvailable,
  normalizeTimePeriodType,
} from 'utils/timePeriod/timePeriodAvailability';

import { FilterConfig } from '../types';

export const dtEndFilterConfig: FilterConfig = {
  key: 'dt_end',
  order: 16,
  isCommon: true,
  parentKey: 'period_type',
  calculator: (filterData) =>
    filterData.time_period?.enabled
      ? (filterData.time_period.default_dt_end ?? null)
      : null,
  dependentDefaultCascadingCalculator: (filterData, currentValues) => {
    const maxDtEnd = filterData.time_period?.max_dt_end;
    const periodType = currentValues.period_type;
    if (!filterData.time_period?.enabled || !maxDtEnd || !periodType) {
      return null;
    }

    const normalizedType = normalizeTimePeriodType(periodType);
    if (!normalizedType) return null;
    const defaultEnd = getDefaultTimePeriodEnd(normalizedType, maxDtEnd);
    return (
      deriveTimePeriodSelection(normalizedType, defaultEnd, maxDtEnd)?.dtEnd ??
      null
    );
  },
  validator: (filterData, value) =>
    Boolean(filterData.time_period?.enabled) &&
    isCanonicalMonthStartDate(value),
  contextualValidator: (filterData, periodType, dtEnd) =>
    Boolean(filterData.time_period?.enabled) &&
    isTimePeriodSelectionAvailable(
      periodType,
      dtEnd,
      filterData.time_period?.max_dt_end,
    ),
  metadata: {
    displayName: 'Time Period End',
    description: 'Selected month-end reference date for the Time Period',
  },
};
